insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('658c0bf4-aab8-4aae-8e6c-86b33df73513', 'seed_Cm1jPuhqhffRYn3m73ZnoB8aLdf6', '2026-06-04T19:31:33.000Z', 'Agile Project Management for Oil Sands Projects', 'agile-project-management-for-oil-sands-projects', 'Agile project management: how agile project management cuts cost and schedule risk on Petrochemicals projects in the Oil Sands region. Includes a checklist for owners, contractors and site teams working through the next season.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'project-management'), 'Agile project management', array['CAPEX optimization services'], '{}', 'EPCMst Team', '2026-07-25', 'When Petrochemicals owners in the Oil Sands region search for "Agile project management", they usually want one thing: a project that stays on budget and on schedule. Regulators and Indigenous partners expect early, honest engagement, and projects go smoother when they get it. Clear interfaces between contractors prevent the gaps where most rework begins. That means naming one accountable person and a clear decision date. Lessons learned only count if the next project actually reads them.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('4d5d95a6-db9a-4aaf-9695-135a038cd782', 'seed_YWjh9AwdSytSZsq1E747SMxLfBBW', '2026-04-22T12:33:44.000Z', 'The Case for EPC Contract Management on Power and Utilities Projects', 'the-case-for-epc-contract-management-on-power-and-utilities-projects', 'Practical lessons from Power and Utilities projects in the Oil Sands region on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'c2b-c2c-contracts'), 'EPC contracts', array['Pipeline engineering specialists'], array['c2b-c2c-contracts', 'power and utilities', 'oil sands'], 'EPCMst Team', '2026-05-15', 'When Power and Utilities owners in the Oil Sands region search for "EPC contracts", they usually want one thing: a project that stays on budget and on schedule. The first step is agreeing what a good outcome looks like before the design is frozen. The cheapest change is the one made on paper; the most expensive is the one made in steel. Vendors respond better when expectations are written down and measured the same way every time. Digital tools help, but only if the people using them trust the information inside.
