insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('6f142627-c70e-4ff8-9a13-9d8b347dd466', 'seed_tHAHMc03w9NWR52Tf4ZRovzKoGJb', '2026-06-27T11:16:01.000Z', 'EPC Contracts on Petrochemicals Sites: Common Pitfalls', 'epc-contracts-on-petrochemicals-sites-common-pitfalls', 'EPC contracts for Petrochemicals owners in northern Alberta: where projects go wrong and what good looks like.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'c2b-c2c-contracts'), 'EPC contracts', array['Agile project management'], array['c2b-c2c-contracts', 'petrochemicals'], 'EPCMst Team', '2026-08-07', 'When Petrochemicals owners in northern Alberta search for "EPC contracts", they usually want one thing: a project that stays on budget and on schedule. Owners who treat EPC contract management as a box to tick usually discover the cost during construction. Good EPC contract management is mostly about communication between engineering, procurement and the field. Field crews should be involved before drawings are issued for construction, not after. The cheapest change is the one made on paper; the most expensive is the one made in steel.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('7de8c128-8193-4adb-bf3d-2cc74893b60e', 'seed_pVRrYBRo642RShw5H1008s5A5K6W', '2026-08-07T03:17:55.000Z', 'Claims: Lessons from a British Columbia Tailings Facility', 'claims-lessons-from-a-british-columbia-tailings-facility', 'Practical lessons from Renewables projects in British Columbia on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'case-study'), (select id from public.service_areas where slug = 'c2b-c2c-contracts'), 'Claims', array['Pre-vetted EPCM specialists'], array['c2b-c2c-contracts', 'renewables', 'british columbia'], 'EPCMst Team', '2026-10-04', 'When Renewables owners in British Columbia search for "Claims", they usually want one thing: a project that stays on budget and on schedule. Data from the last turnaround is the best predictor of the next one, if anyone kept it. The cheapest change is the one made on paper; the most expensive is the one made in steel. On Renewables projects in British Columbia, claims management is often decided early and paid for late. That means naming one accountable person and a clear decision date.
