insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('a8515a18-b576-4532-8ad6-f67437f1c267', 'seed_CSnhdAXB2ZNtx1vNRPco8CgcXuLi', '2026-06-04T10:11:38.000Z', 'A Practical Guide to Design-Build Delivery in Water and Wastewater', 'a-practical-guide-to-design-build-delivery-in-water-and-wastewater', 'Design build: how design-build delivery cuts cost and schedule risk on Water and Wastewater projects in British Columbia.', (select id from public.content_types where slug = 'whitepaper'), (select id from public.service_areas where slug = 'construction'), 'Design build', '{}', '{}', 'EPCMst Team', null, 'When Water and Wastewater owners in British Columbia search for "Design build", they usually want one thing: a project that stays on budget and on schedule. Our teams have seen the same pattern across several Water and Wastewater sites: small gaps early become schedule slips later. On Water and Wastewater projects in British Columbia, design-build delivery is often decided early and paid for late. Vendors respond better when expectations are written down and measured the same way every time. Clear interfaces between contractors prevent the gaps where most rework begins.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('3071ff01-3ea1-4d4c-8520-913007a7c61c', 'seed_UMtSc0Bm115HAwXe0SUnFEKjZTUh', '2026-05-01T13:00:10.000Z', 'Integrated EPC Solutions on Power and Utilities Sites: Common Pitfalls', null, null, (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'engineering'), 'Integrated EPC solutions', array['Construction project management'], array['engineering', 'power and utilities'], 'EPCMst Team', '2026-06-13', 'When Power and Utilities owners in Saskatchewan search for "Integrated EPC solutions", they usually want one thing: a project that stays on budget and on schedule. The cheapest change is the one made on paper; the most expensive is the one made in steel. The first step is agreeing what a good outcome looks like before the design is frozen. Owners who treat integrated EPC delivery as a box to tick usually discover the cost during construction. Vendors respond better when expectations are written down and measured the same way every time.
insert into public.articles (id, drive_file_id, drive_modified_at, title, slug, meta_description, content_type_id, service_area_id, target_keyword, secondary_keywords, tags, author_name, publish_date, body_markdown, status, owner_id, submitted_at, approved_by, approved_at, published_at, published_url, created_at, updated_at) values ('7d29a569-9055-4101-ae33-a9c12698d671', 'seed_1HwXhfSXhyzyE2PkniidmQLeSypn', '2026-09-02T17:26:22.000Z', 'Construction Management on Renewables Sites: Common Pitfalls', null, 'Practical lessons from Renewables projects in Western Canada on reducing cost and schedule risk before construction starts.', (select id from public.content_types where slug = 'technical-insight'), (select id from public.service_areas where slug = 'worksite-management'), 'Construction management', array['Procurement'], '{}', 'EPCMst Team', '2026-11-10', 'When Renewables owners in Western Canada search for "Construction management", they usually want one thing: a project that stays on budget and on schedule. When equipment arrives late, every downstream trade waits, and the camp costs keep running. Owners who treat construction management as a box to tick usually discover the cost during construction. Measuring progress weekly, with the same yardstick, keeps surprises small. Digital tools help, but only if the people using them trust the information inside.
